def cascade_cost_estimate(uploads_per_sec=10000, tier1_drop_rate=0.70):
    gpu_rps = uploads_per_sec * (1.0 - tier1_drop_rate)
    return {'cpu_rps': uploads_per_sec, 'gpu_rps': int(gpu_rps)}

def is_perceptual_match(hash_a_int, hash_b_int, max_hamming=31):
    dist = (hash_a_int ^ hash_b_int).bit_count()
    return dist <= max_hamming

def classify_meme(img_emb, ocr_text, caption):
    # Benign text + benign image can still be toxic together
    fused = cross_attention_fusion(img_emb, text_encoder(ocr_text + ' ' + caption))
    return policy_head(fused)

def route_moderation_verdict(score, view_velocity, is_spam_bot):
    if score >= 0.95:
        return 'AUTO_TAKEDOWN'
    if is_spam_bot and score >= 0.70:
        return 'SHADOWBAN'
    if score >= 0.60:
        return f'HUMAN_QUEUE_PRIORITY_{min(10, int(view_velocity // 100))}'
    return 'PUBLISH'

def normalize_adversarial_text(text):
    nfkc = unicodedata.normalize('NFKC', text)
    # Strip zero-width joiners/spaces
    return ''.join(ch for ch in nfkc if unicodedata.category(ch) != 'Cf')

def distill_llm_edge_case(content, rubric):
